{"path":"app/src/main/java/com/example/snake/MainActivity.kt","content":"package com.example.snake

import android.app.Activity
import android.os.Bundle
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Paint
import android.graphics.RectF
import android.view.MotionEvent
import android.view.View
import kotlin.math.abs
import kotlin.math.min
import kotlin.random.Random

class MainActivity : Activity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        window.statusBarColor = Color.rgb(13, 29, 23)
        window.navigationBarColor = Color.rgb(9, 20, 17)
        setContentView(SnakeView())
    }

    private inner class SnakeView : View(this@MainActivity) {
        private data class Cell(val x: Int, val y: Int)
        private enum class Direction { UP, DOWN, LEFT, RIGHT }

        private val background = Color.rgb(9, 20, 17)
        private val panel = Color.rgb(16, 38, 29)
        private val boardColor = Color.rgb(12, 29, 23)
        private val gridColor = Color.rgb(23, 51, 39)
        private val green = Color.rgb(89, 214, 138)
        private val greenBright = Color.rgb(129, 239, 164)
        private val coral = Color.rgb(255, 121, 105)
        private val textColor = Color.rgb(226, 242, 231)
        private val muted = Color.rgb(145, 177, 157)
        private val paint = Paint(Paint.ANTI_ALIAS_FLAG)
        private val snake = ArrayList<Cell>()
        private val columns = 18
        private val rows = 24
        private var food = Cell(12, 12)
        private var direction = Direction.RIGHT
        private var queuedDirection = Direction.RIGHT
        private var score = 0
        private var gameOver = false
        private var downX = 0f
        private var downY = 0f
        private var boardLeft = 0f
        private var boardTop = 0f
        private var cellSize = 0f
        private var lastStep = 0L
        private val ticker = object : Runnable {
            override fun run() {
                if (!gameOver) {
                    val now = System.currentTimeMillis()
                    if (now - lastStep >= stepDelay()) {
                        move()
                        lastStep = now
                    }
                    invalidate()
                    postDelayed(this, 16L)
                }
            }
        }

        init {
            setBackgroundColor(background)
            restart()
        }

        private fun stepDelay(): Long = (175L - score / 4 * 9L).coerceAtLeast(72L)

        private fun restart() {
            snake.clear()
            snake.add(Cell(5, 12))
            snake.add(Cell(4, 12))
            snake.add(Cell(3, 12))
            direction = Direction.RIGHT
            queuedDirection = Direction.RIGHT
            score = 0
            gameOver = false
            placeFood()
            lastStep = System.currentTimeMillis()
            removeCallbacks(ticker)
            post(ticker)
            invalidate()
        }

        private fun placeFood() {
            do {
                food = Cell(Random.nextInt(columns), Random.nextInt(rows))
            } while (snake.contains(food))
        }

        private fun move() {
            direction = queuedDirection
            val head = snake[0]
            val next = when (direction) {
                Direction.UP -> Cell(head.x, head.y - 1)
                Direction.DOWN -> Cell(head.x, head.y + 1)
                Direction.LEFT -> Cell(head.x - 1, head.y)
                Direction.RIGHT -> Cell(head.x + 1, head.y)
            }
            if (next.x !in 0 until columns || next.y !in 0 until rows || snake.contains(next)) {
                gameOver = true
                invalidate()
                return
            }
            snake.add(0, next)
            if (next == food) {
                score++
                placeFood()
            } else {
                snake.removeAt(snake.lastIndex)
            }
        }

        private fun setDirection(newDirection: Direction) {
            val opposite = when (direction) {
                Direction.UP -> Direction.DOWN
                Direction.DOWN -> Direction.UP
                Direction.LEFT -> Direction.RIGHT
                Direction.RIGHT -> Direction.LEFT
            }
            if (newDirection != opposite) queuedDirection = newDirection
        }

        override fun onDraw(canvas: Canvas) {
            super.onDraw(canvas)
            canvas.drawColor(background)
            val width = width.toFloat()
            val height = height.toFloat()
            paint.typeface = android.graphics.Typeface.create("sans", android.graphics.Typeface.BOLD)
            paint.color = textColor
            paint.textSize = 28f * resources.displayMetrics.scaledDensity
            canvas.drawText("SNAKE", 24f, 42f * resources.displayMetrics.density, paint)

            paint.color = muted
            paint.textSize = 12f * resources.displayMetrics.scaledDensity
            paint.typeface = android.graphics.Typeface.create("sans", android.graphics.Typeface.NORMAL)
            canvas.drawText("SWIPE TO MOVE", 24f, 64f * resources.displayMetrics.density, paint)

            val density = resources.displayMetrics.density
            val side = min(width - 32f * density, height - 142f * density)
            cellSize = side / columns
            boardLeft = (width - side) / 2f
            boardTop = 88f * density
            paint.color = panel
            canvas.drawRoundRect(RectF(boardLeft - 7f * density, boardTop - 7f * density, boardLeft + side + 7f * density, boardTop + side * rows / columns + 7f * density), 14f * density, 14f * density, paint)
            val boardHeight = cellSize * rows
            paint.color = boardColor
            canvas.drawRoundRect(RectF(boardLeft, boardTop, boardLeft + side, boardTop + boardHeight), 9f * density, 9f * density, paint)

            paint.color = gridColor
            paint.strokeWidth = 1f
            for (x in 1 until columns) canvas.drawLine(boardLeft + x * cellSize, boardTop, boardLeft + x * cellSize, boardTop + boardHeight, paint)
            for (y in 1 until rows) canvas.drawLine(boardLeft, boardTop + y * cellSize, boardLeft + side, boardTop + y * cellSize, paint)

            drawFood(canvas, density)
            drawSnake(canvas, density)

            val footerY = boardTop + boardHeight + 46f * density
            paint.color = muted
            paint.textSize = 12f * density
            paint.typeface = android.graphics.Typeface.create("sans", android.graphics.Typeface.BOLD)
            canvas.drawText("SCORE", boardLeft, footerY, paint)
            paint.color = textColor
            paint.textSize = 25f * density
            canvas.drawText(score.toString().padStart(2, '0'), boardLeft, footerY + 27f * density, paint)
            paint.color = muted
            paint.textSize = 12f * density
            canvas.drawText("BEST RUN", boardLeft + side - 72f * density, footerY, paint)
            paint.color = greenBright
            paint.textSize = 25f * density
            canvas.drawText(score.toString().padStart(2, '0'), boardLeft + side - 72f * density, footerY + 27f * density, paint)

            if (gameOver) drawGameOver(canvas, density, side, boardHeight)
        }

        private fun drawFood(canvas: Canvas, density: Float) {
            val cx = boardLeft + food.x * cellSize + cellSize / 2
            val cy = boardTop + food.y * cellSize + cellSize / 2
            paint.color = coral
            canvas.drawCircle(cx, cy, cellSize * .31f, paint)
            paint.color = Color.rgb(255, 180, 130)
            canvas.drawCircle(cx - cellSize * .1f, cy - cellSize * .1f, cellSize * .08f, paint)
        }

        private fun drawSnake(canvas: Canvas, density: Float) {
            snake.forEachIndexed { index, cell ->
                val inset = cellSize * .11f
                val rect = RectF(boardLeft + cell.x * cellSize + inset, boardTop + cell.y * cellSize + inset, boardLeft + (cell.x + 1) * cellSize - inset, boardTop + (cell.y + 1) * cellSize - inset)
                paint.color = if (index == 0) greenBright else green
                canvas.drawRoundRect(rect, cellSize * .2f, cellSize * .2f, paint)
                if (index == 0) {
                    paint.color = Color.rgb(8, 54, 34)
                    val eye = cellSize * .075f
                    val ex = if (direction == Direction.LEFT) rect.left + rect.width() * .28f else rect.left + rect.width() * .72f
                    canvas.drawCircle(ex, rect.top + rect.height() * .32f, eye, paint)
                    canvas.drawCircle(ex, rect.top + rect.height() * .68f, eye, paint)
                }
            }
        }

        private fun drawGameOver(canvas: Canvas, density: Float, side: Float, boardHeight: Float) {
            paint.color = Color.argb(205, 7, 18, 14)
            canvas.drawRoundRect(RectF(boardLeft, boardTop, boardLeft + side, boardTop + boardHeight), 9f * density, 9f * density, paint)
            paint.textAlign = Paint.Align.CENTER
            paint.color = textColor
            paint.typeface = android.graphics.Typeface.create("sans", android.graphics.Typeface.BOLD)
            paint.textSize = 27f * density
            canvas.drawText("RUN OVER", boardLeft + side / 2, boardTop + boardHeight / 2 - 16f * density, paint)
            paint.color = muted
            paint.typeface = android.graphics.Typeface.DEFAULT
            paint.textSize = 14f * density
            canvas.drawText("Score  $score", boardLeft + side / 2, boardTop + boardHeight / 2 + 12f * density, paint)
            paint.color = greenBright
            paint.textSize = 13f * density
            canvas.drawText("TAP TO RESTART", boardLeft + side / 2, boardTop + boardHeight / 2 + 48f * density, paint)
            paint.textAlign = Paint.Align.LEFT
        }

        override fun onTouchEvent(event: MotionEvent): Boolean {
            when (event.actionMasked) {
                MotionEvent.ACTION_DOWN -> {
                    downX = event.x
                    downY = event.y
                    return true
                }
                MotionEvent.ACTION_UP -> {
                    val dx = event.x - downX
                    val dy = event.y - downY
                    if (gameOver && abs(dx) < 30f && abs(dy) < 30f) {
                        restart()
                        return true
                    }
                    if (abs(dx) > abs(dy) && abs(dx) > 30f) {
                        setDirection(if (dx > 0) Direction.RIGHT else Direction.LEFT)
                    } else if (abs(dy) > 30f) {
                        setDirection(if (dy > 0) Direction.DOWN else Direction.UP)
                    }
                    return true
                }
            }
            return true
        }
    }
}
